{"file_path":"src/parseElection.js","content":"/**
 * Parses an election description read from standard input into declared
 * candidate names and validated ballots.
 */

export class ParseError extends Error {}

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

function fail(message) {
  throw new ParseError(message)
}

/**
 * @param {string} text raw standard input
 * @returns {{ candidates: string[], ballots: { count: bigint, names: string[] }[] }}
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  let candidateSet = null
  const ballots = []

  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail(`line ${lineNumber}: expected candidates <name>...`)
      }
      const set = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          fail(`line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (set.has(name)) {
          fail(`line ${lineNumber}: candidate ${name} is declared twice`)
        }
        set.add(name)
      }
      candidates = names
      candidateSet = set
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        fail(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      const countToken = tokens[1]
      if (!COUNT_PATTERN.test(countToken)) {
        fail(`line ${lineNumber}: count must be a positive integer`)
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countToken), names })
    } else {
      fail(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    fail('no candidates')
  }

  return { candidates, ballots }
}
"}

