{"file_path":"src/election.js","content":"/**
 * Counts an instant-runoff election given the declared candidate names and
 * validated ballots, producing every round's tallies and the eventual
 * winner (if any).
 */

/**
 * Chooses which of the tied-for-fewest candidates to eliminate.
 *
 * Ties are broken by comparing the candidates' vote counts across every
 * round counted so far, starting from the first round: at the first round
 * where the tied candidates' counts are not all equal, only those with the
 * fewest votes in that round survive, and the comparison restarts from the
 * first round among the survivors. A tie that no round breaks is resolved
 * by eliminating the name that sorts last by code point.
 *
 * @param {string[]} tiedNames
 * @param {Map<string, bigint>[]} roundsHistory votes per round, earliest first
 * @returns {string}
 */
function pickEliminated(tiedNames, roundsHistory) {
  let tied = tiedNames
  while (tied.length > 1) {
    let narrowed = null
    for (const roundVotes of roundsHistory) {
      const values = tied.map((name) => roundVotes.get(name))
      if (!values.every((v) => v === values[0])) {
        const min = values.reduce((a, b) => (b < a ? b : a))
        narrowed = tied.filter((name) => roundVotes.get(name) === min)
        break
      }
    }
    if (narrowed === null) break
    tied = narrowed
  }
  if (tied.length === 1) return tied[0]
  return tied.slice().sort().pop()
}

/**
 * @param {string[]} candidateNames
 * @param {{ count: bigint, names: string[] }[]} ballots
 * @returns {{ rounds: { number: number, entries: [string, bigint][], exhausted: bigint, eliminated: string | null }[], winner: string | null }}
 */
export function runElection(candidateNames, ballots) {
  const continuing = new Set(candidateNames)
  const roundsHistory = []
  const rounds = []
  let winner = null
  let roundNumber = 0

  while (true) {
    roundNumber++
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else votes.set(choice, votes.get(choice) + ballot.count)
    }

    roundsHistory.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    const entries = [...votes.entries()].sort(([nameA, votesA], [nameB, votesB]) => {
      if (votesA !== votesB) return votesB > votesA ? 1 : -1
      return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
    })

    let roundWinner = null
    let eliminated = null

    if (activeTotal > 0n) {
      for (const [name, v] of votes) {
        if (v * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
      if (roundWinner === null) {
        let min = null
        for (const v of votes.values()) {
          if (min === null || v < min) min = v
        }
        const tied = [...votes.keys()].filter((name) => votes.get(name) === min)
        eliminated = pickEliminated(tied, roundsHistory)
      }
    }

    rounds.push({ number: roundNumber, entries, exhausted, eliminated })

    if (activeTotal === 0n) break
    if (roundWinner !== null) {
      winner = roundWinner
      break
    }
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
